P = [
 dict(pmid='43036674', doi='10.1016/j.eehl.2026.100289', journal='Eco-Environment & Health', title='Monitoring and modelling of indoor environmental quality to guide indoor greening applications.', short='GCARE review 60 studies indoor green infrastructure IEQ monitoring modelling VOC PM removal', design='Systematic review', pm='Indoor PM and VOCs with temperature, humidity and CO2 as monitored in 60 indoor-greening studies', geo="Global / multi-region", endpoint='Indoor environmental quality change attributable to indoor green infrastructure', tier='C', basis='Review / no primary exposure', affil='University of Surrey (GCARE), United Kingdom; Federal Institute of Hydrology, Germany', n="Review of 60 studies of passive (potted plants, green walls, indoor trees) and active (hydroponics, biofilters) indoor greening and indoor environmental quality. Passive systems typically cut VOCs 10-30% and buffer temperature and humidity; active systems removed VOCs and PM more efficiently. 59% of studies were laboratory, 33% in situ, many with 6-48 h chamber runs; controlled settings overstate removal relative to real buildings, and descriptors and ventilation data are not standardised. Passive configurations reduced cooling demand 22-27%. No PM removal rate is quantified in the abstract, and the evidence is dominated by short chamber tests with few taxa. Relevance: moderate - the review's main ask, long in-situ IEQ monitoring with ventilation logging, is a direct job for indoor low-cost PM/CO2 nodes.", sub=corpus.OCC),
 dict(pmid='', doi='10.5194/amt-19-7467-2026', journal='Atmospheric Measurement Techniques', title='First observations of aerosol mass fluxes over open water using a large-aperture scintillometer', short='Eastern China lake and coastal bay large-aperture scintillometer aerosol mass flux RMN(RH) PM10 calibration', design='Measurement campaign', pm='Path-averaged aerosol mass flux from large-aperture scintillometer log-intensity spectra; conversion factor calibrated against PM10, visibility and RH', geo='China (eastern; inland lake and coastal bay)', endpoint='Aerosol mass-flux magnitude over open water', tier='B', basis='Lab / research instrument', affil='not stated in record', n='First large-aperture scintillometer (LAS) retrieval of path-averaged aerosol mass flux over open water, four campaigns at an inland lake and a coastal bay in eastern China. The aerosol (imaginary) and thermodynamic (real) refractive-index contributions were separated from the log-intensity spectrum, and the constant mass-to-optical conversion factor was replaced by a campaign-specific RMN(RH) calibrated against PM10, visibility and RH; RMN fell consistently with humidity. Campaign-median flux magnitudes were 0.091-0.399 ug m-2 s-1, with daytime enhancement; dense coastal fog was the main operational limit. Magnitudes only (no sign), validation is against calculated dry deposition rather than eddy covariance, and n=4 campaigns. Relevance: moderate - the RH-dependent optical-to-mass conversion is the same hygroscopic problem that biases optical low-cost PM sensors.', sub=corpus.SENS),
 dict(pmid='', doi='10.5194/acp-26-16151-2026', journal='Atmospheric Chemistry and Physics', title='Vertically stratified long-range transport of biomass-burning aerosol over Reunion Island during September 2017', short='Reunion Island September 2017 biomass-burning aerosol layers lidar AERONET FTIR CO CAMS FLEXPART', design='Episode analysis (observations + model)', pm='AERONET AOD 550 nm, Raman/elastic lidar layers, CALIOP, MODIS, CAMS EAC4 reanalysis; FLEXPART source attribution', geo='Reunion Island (France, SW Indian Ocean)', endpoint='Vertical structure and source of free-tropospheric smoke layers', tier='C', basis='Lab / research instrument', affil='not stated in record', n='Case study of a September 2017 biomass-burning aerosol episode over Reunion Island combining AERONET, ground lidar, FTIR CO, MODIS, CALIOP, CAMS EAC4 and FLEXPART. AOD at 550 nm reached 0.16-0.42. Lidar resolved one layer at 2.8-4.7 km on 19 September (Angstrom 355/532 = 1.32 +/- 0.23) and two on 25 September: 3.3-5 km (1.45 +/- 0.12) and a drier 5-9 km layer (1.60 +/- 0.06). FLEXPART, checked against smoothed FTIR CO, attributes both to southern Africa with a South American contribution to the lower layer. Two days in one month; layers sit in the free troposphere, so surface PM implications are not addressed. Relevance: low - column/vertical context only; a reminder that column AOD in satellite-fusion models can be decoupled from surface PM.', sub=corpus.EXPO),
 dict(pmid='', doi='10.5194/acp-26-16225-2026', journal='Atmospheric Chemistry and Physics', title='Meteorological conditions and aerosol-meteorology feedback drive divergent responses of co-occurring PM 2.5 and O 3 pollution to NO x -VOC perturbations in Beijing-Tianjin-Hebei-Shandong', short='BTHS July 2020 WRF-Chem double-high PM2.5 O3 NOx-VOC perturbation meteorological regimes aerosol feedback', design='Emissions scenario modelling', pm='WRF-Chem simulated PM2.5 and O3 under joint NOx-VOC emission perturbations, five meteorological regimes', geo='China (Beijing-Tianjin-Hebei-Shandong)', endpoint='Modelled PM2.5 and O3 response to precursor reductions', tier='C', basis='Model (CTM / LUR / ML)', affil='not stated in record', n="WRF-Chem for July 2020 over Beijing-Tianjin-Hebei-Shandong, classifying co-occurring PM2.5/O3 'double high' days into five regimes by boundary-layer height, temperature and humidity. PM2.5 was highest under Stable and WarmHumid (~46 ug/m3) and lowest under DryHot (~40); O3 highest under DryHot and Moderate (~163 ug/m3). At 50%/50% NOx/VOC cuts, PM2.5 fell 20.6% (Stable) and 20.9% (WarmHumid) but only 15.2% (DryHot); O3 fell 25.2% (WarmHumid) and 23.3% (DryHot). Aerosol-meteorology feedback amplified PM2.5 reductions in the Stable and WarmHumid regimes. One month, one model, no reported evaluation statistics in the abstract. Relevance: low-moderate - regime-dependent control efficacy is testable with dense sensor networks resolving boundary-layer-driven PM variability.", sub=corpus.EXPO),
]
